-- Startup Act Tunisia — base canonique 88 sessions, réextraction PDF corrigée 2026-08-23
PRAGMA foreign_keys = ON;
DROP TABLE IF EXISTS company_founders; DROP TABLE IF EXISTS founders; DROP TABLE IF EXISTS decisions; DROP TABLE IF EXISTS companies; DROP TABLE IF EXISTS session_official_counts;
CREATE TABLE session_official_counts (session_id TEXT PRIMARY KEY, session TEXT NOT NULL, official_candidatures INTEGER NOT NULL, detailed_entries INTEGER NOT NULL, official_labels INTEGER NOT NULL, official_prelabels INTEGER NOT NULL, conversions INTEGER NOT NULL, official_withdrawals INTEGER NOT NULL, detailed_reportes INTEGER NOT NULL);
CREATE TABLE companies (company_id TEXT PRIMARY KEY, name TEXT NOT NULL, sector TEXT, sessions TEXT);
CREATE TABLE founders (founder_id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE company_founders (company_id TEXT, founder_id TEXT, session_id TEXT, founder_raw TEXT, quality TEXT, PRIMARY KEY(company_id,founder_id,session_id));
CREATE TABLE decisions (decision_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, company_id TEXT, source_file TEXT, section TEXT, project TEXT, founders_raw TEXT, decision_raw TEXT, result_normalized TEXT, sector TEXT, tour TEXT, after_pitching TEXT, award_or_withdrawal TEXT, comments TEXT, quality_control TEXT);
